tool_schemas.implementation:
def tavily_search(query, search_depth=None, max_results=None, include_answer=None, include_raw_content=None, include_images=None, include_domains=None, exclude_domains=None, start_date=None, end_date=None, topic=None, time_range=None, workspace_id=None, **_extra):
    import json, os, datetime, re, hashlib, time
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0256000" if __import__("os").path.isdir("./environment_mix/0256000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _parse_date(s):
        if s is None:
            return None
        try:
            return datetime.date.fromisoformat(s)
        except Exception:
            return None

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _gen_id(prefix):
        # stable-ish unique id without external deps
        t = int(time.time() * 1000)
        r = hashlib.sha256(f"{prefix}:{t}:{os.getpid()}".encode("utf-8")).hexdigest()[:18].upper()
        return f"{prefix}_01H{r}"

    def _registrable_domain(host):
        host = (host or "").lower().strip(".")
        if not host:
            return ""
        parts = [p for p in host.split(".") if p]
        if len(parts) <= 2:
            return host
        return ".".join(parts[-2:])

    def _canonicalize_url(u):
        try:
            p = urlparse(u)
        except Exception:
            return None
        if p.scheme not in ("http", "https"):
            return None
        if not p.netloc:
            return None
        scheme = p.scheme.lower()
        host = p.netloc.lower()
        # strip default ports
        if host.endswith(":80") and scheme == "http":
            host = host[:-3]
        if host.endswith(":443") and scheme == "https":
            host = host[:-4]
        path = p.path or "/"
        # drop fragment, keep query
        q = f"?{p.query}" if p.query else ""
        canon = f"{scheme}://{host}{path}{q}"
        return canon

    def _authenticate_context(workspaces, api_keys, requested_workspace_id):
        # Ambient auth: choose a workspace that can serve the call.
        # Since no credential parameter exists, pick the requested workspace if provided else any active.
        ws = None
        if requested_workspace_id is not None:
            for w in workspaces:
                if w.get("id") == requested_workspace_id:
                    ws = w
                    break
            if ws is None:
                return None, None, _err("NOT_FOUND", "workspace not found", workspace_id=requested_workspace_id)
        else:
            for w in workspaces:
                if w.get("status") == "active":
                    ws = w
                    break
            if ws is None:
                return None, None, _err("UNAUTHORIZED", "no active workspace available")
        # No api_key in tool surface; represent as internal/system call
        return ws, None, None

    def _log_call(tool_calls, workspace_id_val, api_key_id_val, tool_name, status, input_obj, normalized_input_obj=None, error_code=None, error_message=None, estimated_tokens=None, billed_tokens=None, started_at=None, finished_at=None, expires_at=None):
        now = _now_iso()
        row = {
            "id": _gen_id("tav_tc"),
            "workspace_id": workspace_id_val,
            "api_key_id": api_key_id_val,
            "tool_name": tool_name,
            "status": status,
            "requested_at": now,
            "started_at": started_at,
            "finished_at": finished_at,
            "expires_at": expires_at,
            "input": input_obj,
            "normalized_input": normalized_input_obj,
            "error_code": error_code,
            "error_message": error_message,
            "http_user_agent": None,
            "source_ip": None,
            "estimated_tokens": estimated_tokens,
            "billed_tokens": billed_tokens,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        return row

    def _transition_tool_call(row, new_status):
        transitions = {
            "queued": {"running", "cancelled", "failed", "expired"},
            "running": {"succeeded", "failed", "cancelled", "expired"},
            "succeeded": {"expired"},
            "failed": {"expired"},
            "cancelled": {"expired"},
            "expired": set(),
        }
        cur = row.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return _err("INVALID_TRANSITION", f"invalid status transition: {cur} -> {new_status}", from_status=cur, to_status=new_status)
        now = _now_iso()
        if new_status == "running":
            row["started_at"] = row.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled", "expired"):
            if row.get("started_at") is None:
                # must have started_at before finish (except queued->failed etc still requires started_at per rule when running,
                # but for queued->failed/cancelled/expired, started_at may remain null; finished_at set anyway with constraint finished_at>=started_at only if started_at set)
                pass
            row["finished_at"] = now
        row["status"] = new_status
        row["updated_at"] = now
        # enforce finished_at >= started_at when both present
        sa = _parse_dt(row.get("started_at"))
        fa = _parse_dt(row.get("finished_at"))
        if sa and fa and fa < sa:
            row["finished_at"] = row["started_at"]
        return None

    def _ensure_month_rollover(ws):
        now = datetime.datetime.now(datetime.timezone.utc)
        mk = _month_key(now)
        if ws.get("usage_month") != mk:
            ws["usage_month"] = mk
            ws["requests_used_month"] = 0
            ws["tokens_used_month"] = 0
            ws["updated_at"] = _now_iso()

    def _quota_check_request(ws):
        _ensure_month_rollover(ws)
        lim = ws.get("monthly_request_limit")
        used = ws.get("requests_used_month")
        if not isinstance(lim, int) or lim < 0 or not isinstance(used, int) or used < 0:
            return _err("VALIDATION_ERROR", "workspace quota counters/limits invalid")
        if used + 1 > lim:
            return "quota_exceeded"
        return None

    # ---- Validate inputs (before mutating) ----
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if search_depth is not None and search_depth not in ("basic", "advanced"):
        return _err("VALIDATION_ERROR", "search_depth must be one of: basic, advanced")
    if max_results is not None:
        if not isinstance(max_results, int):
            return _err("VALIDATION_ERROR", "max_results must be an integer")
        if max_results < 1 or max_results > 50:
            return _err("VALIDATION_ERROR", "max_results must be between 1 and 50")
    else:
        max_results = 10

    for bname, bval in [
        ("include_answer", include_answer),
        ("include_raw_content", include_raw_content),
        ("include_images", include_images),
    ]:
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean")

    if include_domains is not None:
        if not isinstance(include_domains, list) or any(not isinstance(x, str) or not x.strip() for x in include_domains):
            return _err("VALIDATION_ERROR", "include_domains must be an array of non-empty strings")
    if exclude_domains is not None:
        if not isinstance(exclude_domains, list) or any(not isinstance(x, str) or not x.strip() for x in exclude_domains):
            return _err("VALIDATION_ERROR", "exclude_domains must be an array of non-empty strings")

    sd = _parse_date(start_date)
    if start_date is not None and sd is None:
        return _err("VALIDATION_ERROR", "start_date must be YYYY-MM-DD")
    ed = _parse_date(end_date)
    if end_date is not None and ed is None:
        return _err("VALIDATION_ERROR", "end_date must be YYYY-MM-DD")
    if sd and ed and ed < sd:
        return _err("VALIDATION_ERROR", "end_date must be on/after start_date")

    if topic is not None and topic not in ("general", "news"):
        return _err("VALIDATION_ERROR", "topic must be one of: general, news")
    if time_range is not None and time_range not in ("day", "week", "month", "year"):
        return _err("VALIDATION_ERROR", "time_range must be one of: day, week, month, year")

    if workspace_id is not None:
        if not isinstance(workspace_id, str) or re.match(r"^tav_ws_01H[0-9A-Z]{15,}$", workspace_id) is None:
            return _err("VALIDATION_ERROR", "workspace_id format is invalid")

    # ---- Load datastore / resolve context ----
    ws_rows = _load("workspaces.json")
    key_rows = _load("api_keys.json")
    tc_rows = _load("tool_calls.json")
    wr_rows = _load("web_resources.json")
    tcr_rows = _load("tool_call_results.json")

    ws, api_key_id_val, auth_err = _authenticate_context(ws_rows, key_rows, workspace_id)
    if auth_err:
        # record attempt? no workspace available to attribute -> cannot log reliably; return error
        return auth_err

    # ---- Create tool_call row (always) ----
    input_obj = {
        "query": query,
        "search_depth": search_depth,
        "max_results": max_results,
        "include_answer": include_answer,
        "include_raw_content": include_raw_content,
        "include_images": include_images,
        "include_domains": include_domains,
        "exclude_domains": exclude_domains,
        "start_date": start_date,
        "end_date": end_date,
        "topic": topic,
        "time_range": time_range,
        "workspace_id": workspace_id,
    }
    normalized = {
        "query": query.strip(),
        "search_depth": search_depth or "basic",
        "max_results": max_results,
        "include_answer": bool(include_answer) if include_answer is not None else False,
        "include_raw_content": bool(include_raw_content) if include_raw_content is not None else False,
        "include_images": bool(include_images) if include_images is not None else False,
        "include_domains": [d.lower() for d in include_domains] if include_domains else None,
        "exclude_domains": [d.lower() for d in exclude_domains] if exclude_domains else None,
        "start_date": start_date,
        "end_date": end_date,
        "topic": topic or "general",
        "time_range": time_range,
    }

    tc = _log_call(
        tc_rows,
        ws.get("id"),
        api_key_id_val,
        "tavily-search",
        "queued",
        input_obj,
        normalized_input_obj=normalized,
        estimated_tokens=0,
    )
    _save("tool_calls.json", tc_rows)

    # ---- Enforce workspace active + request quota before "accepting" ----
    if ws.get("status") != "active":
        tc["error_code"] = "quota_exceeded"
        tc["error_message"] = "workspace is not active"
        _transition_tool_call(tc, "failed")
        _save("tool_calls.json", tc_rows)
        return _err("QUOTA_EXCEEDED", "workspace is not active", tool_call_id=tc["id"])

    quota_err = _quota_check_request(ws)
    if quota_err:
        tc["error_code"] = "quota_exceeded"
        tc["error_message"] = "monthly request limit exceeded"
        _transition_tool_call(tc, "failed")
        _save("tool_calls.json", tc_rows)
        return _err("QUOTA_EXCEEDED", "monthly request limit exceeded", tool_call_id=tc["id"])

    # ---- Execute (local synthesis from datastore) ----
    trans_err = _transition_tool_call(tc, "running")
    if trans_err:
        tc["error_code"] = "invalid_transition"
        tc["error_message"] = trans_err["error"]["message"]
        _save("tool_calls.json", tc_rows)
        return trans_err
    _save("tool_calls.json", tc_rows)

    q = query.strip().lower()
    inc = set([d.lower() for d in include_domains]) if include_domains else None
    exc = set([d.lower() for d in exclude_domains]) if exclude_domains else set()

    # Score based on simple term overlap in title/content/url
    terms = [t for t in re.split(r"\s+", q) if t]
    hits = []
    for wr in wr_rows:
        cu = wr.get("canonical_url") or ""
        dom = (wr.get("domain") or "").lower()
        if inc is not None and dom not in inc:
            continue
        if dom in exc:
            continue
        blob = " ".join([
            (wr.get("title") or ""),
            (wr.get("clean_content") or ""),
            (wr.get("raw_content") or ""),
            cu,
            dom,
        ]).lower()
        score = 0
        for t in terms:
            if t in blob:
                score += 1
        if score <= 0:
            continue
        hits.append((score, wr))

    hits.sort(key=lambda x: (-x[0], x[1].get("updated_at") or "", x[1].get("id") or ""))

    out_hits = hits[:max_results]
    results = []
    rank = 1
    now_iso = _now_iso()

    for score, wr in out_hits:
        # Ensure canonical_url / url_hash exist; if not, skip malformed rows
        cu = wr.get("canonical_url")
        if not isinstance(cu, str) or not cu.startswith("http"):
            continue

        # Create tool_call_results row
        res_id = _gen_id("tav_tcr")
        payload = {
            "url": cu,
            "title": wr.get("title"),
            "content": None,
            "raw_content": None,
            "score": float(score),
            "search_depth": normalized["search_depth"],
            "domain": wr.get("domain"),
        }
        if normalized["include_raw_content"]:
            # Respect robots policy: do not return/store content if disallowed
            if wr.get("robots_allowed") is False:
                payload["raw_content"] = None
                payload["content"] = None
                payload["robots_allowed"] = False
            else:
                payload["raw_content"] = wr.get("raw_content")
                payload["content"] = wr.get("clean_content") or (wr.get("raw_content")[:500] if isinstance(wr.get("raw_content"), str) else None)
                payload["robots_allowed"] = True
        else:
            payload["content"] = (wr.get("clean_content") or "")[:300] if isinstance(wr.get("clean_content"), str) else None

        tcr = {
            "id": res_id,
            "tool_call_id": tc["id"],
            "workspace_id": ws.get("id"),
            "kind": "search_hit",
            "rank": rank,
            "web_resource_id": wr.get("id"),
            "from_web_resource_id": None,
            "to_web_resource_id": None,
            "payload": payload,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tcr_rows.append(tcr)
        results.append(payload)
        rank += 1

    # synthesized answer (deterministic summary)
    answer = None
    if normalized["include_answer"]:
        if results:
            titles = [r.get("title") for r in results if r.get("title")]
            answer = f"Top results for '{query.strip()}': " + (", ".join(titles[:5]) if titles else "relevant pages found.")
        else:
            answer = f"No matching results found for '{query.strip()}' in the local index."

    # images: none in local schema; return empty list if requested
    images = []
    if normalized["include_images"]:
        images = []

    # ---- Success: bill tokens atomically and persist ----
    # For search: billed_tokens minimal (0) but still counts request.
    billed_tokens = 0
    # Apply usage
    _ensure_month_rollover(ws)
    ws["requests_used_month"] = int(ws.get("requests_used_month", 0)) + 1
    ws["tokens_used_month"] = int(ws.get("tokens_used_month", 0)) + billed_tokens
    ws["updated_at"] = _now_iso()
    tc["billed_tokens"] = billed_tokens

    trans_err = _transition_tool_call(tc, "succeeded")
    if trans_err:
        tc["error_code"] = "invalid_transition"
        tc["error_message"] = trans_err["error"]["message"]
        _save("tool_calls.json", tc_rows)
        return trans_err

    _save("workspaces.json", ws_rows)
    _save("tool_call_results.json", tcr_rows)
    _save("tool_calls.json", tc_rows)

    return {
        "tool_call_id": tc["id"],
        "query": query,
        "answer": answer,
        "results": results,
        "images": images,
        "max_results": max_results,
        "usage": {
            "billed_tokens": billed_tokens,
            "requests_used_month": ws["requests_used_month"],
            "tokens_used_month": ws["tokens_used_month"],
            "usage_month": ws["usage_month"],
        },
    }

def tavily_extract(urls, include_raw_content=None, include_images=None, extract_depth=None, max_chars=None, workspace_id=None, **_extra):
    import json, os, datetime, re, hashlib, time
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0256000" if __import__("os").path.isdir("./environment_mix/0256000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _gen_id(prefix):
        t = int(time.time() * 1000)
        r = hashlib.sha256(f"{prefix}:{t}:{os.getpid()}".encode("utf-8")).hexdigest()[:18].upper()
        return f"{prefix}_01H{r}"

    def _registrable_domain(host):
        host = (host or "").lower().strip(".")
        if not host:
            return ""
        parts = [p for p in host.split(".") if p]
        if len(parts) <= 2:
            return host
        return ".".join(parts[-2:])

    def _canonicalize_url(u):
        try:
            p = urlparse(u)
        except Exception:
            return None
        if p.scheme not in ("http", "https"):
            return None
        if not p.netloc:
            return None
        scheme = p.scheme.lower()
        host = p.netloc.lower()
        if host.endswith(":80") and scheme == "http":
            host = host[:-3]
        if host.endswith(":443") and scheme == "https":
            host = host[:-4]
        path = p.path or "/"
        q = f"?{p.query}" if p.query else ""
        return f"{scheme}://{host}{path}{q}"

    def _url_hash(canon):
        return hashlib.sha256(canon.encode("utf-8")).hexdigest()

    def _content_hash(s):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _authenticate_context(workspaces, api_keys, requested_workspace_id):
        ws = None
        if requested_workspace_id is not None:
            for w in workspaces:
                if w.get("id") == requested_workspace_id:
                    ws = w
                    break
            if ws is None:
                return None, None, _err("NOT_FOUND", "workspace not found", workspace_id=requested_workspace_id)
        else:
            for w in workspaces:
                if w.get("status") == "active":
                    ws = w
                    break
            if ws is None:
                return None, None, _err("UNAUTHORIZED", "no active workspace available")
        return ws, None, None

    def _log_call(tool_calls, workspace_id_val, api_key_id_val, tool_name, status, input_obj, normalized_input_obj=None, error_code=None, error_message=None, estimated_tokens=None, billed_tokens=None, started_at=None, finished_at=None, expires_at=None):
        now = _now_iso()
        row = {
            "id": _gen_id("tav_tc"),
            "workspace_id": workspace_id_val,
            "api_key_id": api_key_id_val,
            "tool_name": tool_name,
            "status": status,
            "requested_at": now,
            "started_at": started_at,
            "finished_at": finished_at,
            "expires_at": expires_at,
            "input": input_obj,
            "normalized_input": normalized_input_obj,
            "error_code": error_code,
            "error_message": error_message,
            "http_user_agent": None,
            "source_ip": None,
            "estimated_tokens": estimated_tokens,
            "billed_tokens": billed_tokens,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        return row

    def _transition_tool_call(row, new_status):
        transitions = {
            "queued": {"running", "cancelled", "failed", "expired"},
            "running": {"succeeded", "failed", "cancelled", "expired"},
            "succeeded": {"expired"},
            "failed": {"expired"},
            "cancelled": {"expired"},
            "expired": set(),
        }
        cur = row.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return _err("INVALID_TRANSITION", f"invalid status transition: {cur} -> {new_status}", from_status=cur, to_status=new_status)
        now = _now_iso()
        if new_status == "running":
            row["started_at"] = row.get("started_at") or now
        if new_status in ("succeeded", "failed", "cancelled", "expired"):
            row["finished_at"] = now
        row["status"] = new_status
        row["updated_at"] = now
        sa = _parse_dt(row.get("started_at"))
        fa = _parse_dt(row.get("finished_at"))
        if sa and fa and fa < sa:
            row["finished_at"] = row["started_at"]
        return None

    def _ensure_month_rollover(ws):
        now = datetime.datetime.now(datetime.timezone.utc)
        mk = _month_key(now)
        if ws.get("usage_month") != mk:
            ws["usage_month"] = mk
            ws["requests_used_month"] = 0
            ws["tokens_used_month"] = 0
            ws["updated_at"] = _now_iso()

    def _quota_check_request(ws):
        _ensure_month_rollover(ws)
        lim = ws.get("monthly_request_limit")
        used = ws.get("requests_used_month")
        if not isinstance(lim, int) or lim < 0 or not isinstance(used, int) or used < 0:
            return _err("VALIDATION_ERROR", "workspace quota counters/limits invalid")
        if used + 1 > lim:
            return "quota_exceeded"
        return None

    def _quota_check_tokens(ws, est):
        _ensure_month_rollover(ws)
        lim = ws.get("monthly_token_limit")
        used = ws.get("tokens_used_month")
        if not isinstance(lim, int) or lim < 0 or not isinstance(used, int) or used < 0:
            return _err("VALIDATION_ERROR", "workspace token counters/limits invalid")
        if used + est > lim:
            return "quota_exceeded"
        return None

    def _upsert_web_resource(wr_rows, canon_url, allow_store_content, title=None, raw=None, clean=None, fetch_status=200, content_type="text/html"):
        now = _now_iso()
        uh = _url_hash(canon_url)
        existing = None
        for r in wr_rows:
            if r.get("url_hash") == uh:
                existing = r
                break
        dom = _registrable_domain(urlparse(canon_url).hostname)
        if existing is None:
            row = {
                "id": _gen_id("tav_wr"),
                "canonical_url": canon_url,
                "url_hash": uh,
                "domain": dom,
                "last_fetch_status": fetch_status,
                "last_fetched_at": now,
                "content_type": content_type,
                "content_language": None,
                "content_sha256": None,
                "raw_content": None,
                "clean_content": None,
                "title": title,
                "robots_allowed": bool(allow_store_content),
                "created_at": now,
                "updated_at": now,
            }
            if allow_store_content:
                row["raw_content"] = raw
                row["clean_content"] = clean
                row["content_sha256"] = _content_hash(clean or raw)
            wr_rows.append(row)
            return row
        # upsert
        existing["canonical_url"] = canon_url
        existing["domain"] = dom
        existing["last_fetch_status"] = fetch_status
        existing["last_fetched_at"] = now
        existing["content_type"] = content_type
        if title is not None:
            existing["title"] = title
        # lifecycle for robots_allowed allows toggling
        existing["robots_allowed"] = bool(allow_store_content)
        if allow_store_content:
            existing["raw_content"] = raw
            existing["clean_content"] = clean
            existing["content_sha256"] = _content_hash(clean or raw)
        else:
            # must not store content when disallowed
            existing["raw_content"] = None
            existing["clean_content"] = None
            existing["content_sha256"] = None
        existing["updated_at"] = now
        return existing

    # ---- Validate inputs ----
    if not isinstance(urls, list) or len(urls) < 1:
        return _err("VALIDATION_ERROR", "urls must be a non-empty array")
    for u in urls:
        if not isinstance(u, str) or not u.strip():
            return _err("VALIDATION_ERROR", "urls must contain only non-empty strings")
        cu = _canonicalize_url(u.strip())
        if cu is None:
            return _err("VALIDATION_ERROR", f"invalid url: {u}")

    for bname, bval in [("include_raw_content", include_raw_content), ("include_images", include_images)]:
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean")

    if extract_depth is not None and extract_depth not in ("basic", "advanced"):
        return _err("VALIDATION_ERROR", "extract_depth must be one of: basic, advanced")

    if max_chars is not None:
        if not isinstance(max_chars, int) or max_chars < 1:
            return _err("VALIDATION_ERROR", "max_chars must be an integer >= 1")

    if workspace_id is not None:
        if not isinstance(workspace_id, str) or re.match(r"^tav_ws_01H[0-9A-Z]{15,}$", workspace_id) is None:
            return _err("VALIDATION_ERROR", "workspace_id format is invalid")

    # ---- Load datastore / resolve context ----
    ws_rows = _load("workspaces.json")
    key_rows = _load("api_keys.json")
    tc_rows = _load("tool_calls.json")
    wr_rows = _load("web_resources.json")
    tcr_rows = _load("tool_call_results.json")

    ws, api_key_id_val, auth_err = _authenticate_context(ws_rows, key_rows, workspace_id)
    if auth_err:
        return auth_err

    # ---- Create tool_call row (always) ----
    input_obj = {
        "urls": urls,
        "include_raw_content": include_raw_content,
        "include_images": include_images,
        "extract_depth": extract_depth,
        "max_chars": max_chars,
        "workspace_id": workspace_id,
    }
    norm_urls = [_canonicalize_url(u.strip()) for u in urls]
    normalized = {
        "urls": norm_urls,
        "include_raw_content": bool(include_raw_content) if include_raw_content is not None else False,
        "include_images": bool(include_images) if include_images is not None else False,
        "extract_depth": extract_depth or "basic",
        "max_chars": max_chars,
    }

    # Estimate tokens before execution: proportional to URL count and depth
    base = 200 if normalized["extract_depth"] == "basic" else 400
    est_tokens = base * len(norm_urls)

    tc = _log_call(
        tc_rows,
        ws.get("id"),
        api_key_id_val,
        "tavily-extract",
        "queued",
        input_obj,
        normalized_input_obj=normalized,
        estimated_tokens=est_tokens,
    )
    _save("tool_calls.json", tc_rows)

    # ---- Enforce active + quotas before accept ----
    if ws.get("status") != "active":
        tc["error_code"] = "quota_exceeded"
        tc["error_message"] = "workspace is not active"
        _transition_tool_call(tc, "failed")
        _save("tool_calls.json", tc_rows)
        return _err("QUOTA_EXCEEDED", "workspace is not active", tool_call_id=tc["id"])

    quota_err = _quota_check_request(ws)
    if quota_err:
        tc["error_code"] = "quota_exceeded"
        tc["error_message"] = "monthly request limit exceeded"
        _transition_tool_call(tc, "failed")
        _save("tool_calls.json", tc_rows)
        return _err("QUOTA_EXCEEDED", "monthly request limit exceeded", tool_call_id=tc["id"])

    tq = _quota_check_tokens(ws, est_tokens)
    if tq:
        if isinstance(tq, dict) and tq.get("error"):
            tc["error_code"] = "quota_exceeded"
            tc["error_message"] = tq["error"]["message"]
            _transition_tool_call(tc, "failed")
            _save("tool_calls.json", tc_rows)
            return tq
        tc["error_code"] = "quota_exceeded"
        tc["error_message"] = "monthly token limit exceeded"
        _transition_tool_call(tc, "failed")
        _save("tool_calls.json", tc_rows)
        return _err("QUOTA_EXCEEDED", "monthly token limit exceeded", tool_call_id=tc["id"])

    # ---- Execute ----
    trans_err = _transition_tool_call(tc, "running")
    if trans_err:
        tc["error_code"] = "invalid_transition"
        tc["error_message"] = trans_err["error"]["message"]
        _save("tool_calls.json", tc_rows)
        return trans_err
    _save("tool_calls.json", tc_rows)

    now_iso = _now_iso()
    extracted = []
    any_robots_block = False

    for idx, canon in enumerate(norm_urls, start=1):
        # Policy: if an existing web_resource has robots_allowed false, disallow storing/returning content
        existing = None
        uh = _url_hash(canon)
        for r in wr_rows:
            if r.get("url_hash") == uh:
                existing = r
                break

        robots_allowed = True
        if existing is not None and existing.get("robots_allowed") is False:
            robots_allowed = False

        # Produce deterministic synthetic content if allowed, otherwise none
        title = None
        raw = None
        clean = None
        if robots_allowed:
            title = (existing.get("title") if existing else None) or f"Extracted: {canon}"
            clean = f"Extracted content for {canon} (depth={normalized['extract_depth']})."
            if normalized["extract_depth"] == "advanced":
                clean += " Parsed main text with enhanced heuristics."
            if max_chars is not None:
                clean = clean[:max_chars]
            if normalized["include_raw_content"]:
                raw = (existing.get("raw_content") if existing else None) or (clean + "\n\n[raw]")
        else:
            any_robots_block = True

        wr = _upsert_web_resource(
            wr_rows,
            canon,
            allow_store_content=robots_allowed,
            title=title,
            raw=raw if robots_allowed else None,
            clean=clean if robots_allowed else None,
            fetch_status=200 if robots_allowed else 403,
            content_type="text/html",
        )

        payload = {
            "url": canon,
            "title": wr.get("title"),
            "content": wr.get("clean_content"),
            "raw_content": wr.get("raw_content") if normalized["include_raw_content"] else None,
            "images": [] if normalized["include_images"] else None,
            "content_sha256": wr.get("content_sha256"),
            "robots_allowed": bool(wr.get("robots_allowed")),
            "extract_depth": normalized["extract_depth"],
            "truncated": bool(max_chars is not None and isinstance(wr.get("clean_content"), str) and len(wr.get("clean_content")) >= max_chars),
        }

        # Write tool_call_results (must match workspace)
        tcr_rows.append({
            "id": _gen_id("tav_tcr"),
            "tool_call_id": tc["id"],
            "workspace_id": ws.get("id"),
            "kind": "extracted_document",
            "rank": idx,
            "web_resource_id": wr.get("id"),
            "from_web_resource_id": None,
            "to_web_resource_id": None,
            "payload": payload,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        extracted.append(payload)

    # If robots disallowed affected any URL, mark partial failure per policy
    if any_robots_block:
        tc["error_code"] = "robots_disallowed"
        tc["error_message"] = "one or more URLs disallowed by robots policy"

    # Bill tokens on completion and apply atomically: request + tokens
    billed_tokens = est_tokens
    _ensure_month_rollover(ws)
    ws["requests_used_month"] = int(ws.get("requests_used_month", 0)) + 1
    ws["tokens_used_month"] = int(ws.get("tokens_used_month", 0)) + billed_tokens
    ws["updated_at"] = _now_iso()
    tc["billed_tokens"] = billed_tokens

    trans_err = _transition_tool_call(tc, "succeeded" if not any_robots_block else "failed")
    if trans_err:
        tc["error_code"] = "invalid_transition"
        tc["error_message"] = trans_err["error"]["message"]
        _save("tool_calls.json", tc_rows)
        return trans_err

    _save("workspaces.json", ws_rows)
    _save("web_resources.json", wr_rows)
    _save("tool_call_results.json", tcr_rows)
    _save("tool_calls.json", tc_rows)

    if any_robots_block:
        return _err(
            "CONFLICT",
            "robots policy disallowed content for one or more URLs",
            tool_call_id=tc["id"],
            error_code=tc.get("error_code"),
        )

    return {
        "tool_call_id": tc["id"],
        "results": extracted,
        "usage": {
            "estimated_tokens": est_tokens,
            "billed_tokens": billed_tokens,
            "requests_used_month": ws["requests_used_month"],
            "tokens_used_month": ws["tokens_used_month"],
            "usage_month": ws["usage_month"],
        },
    }

def tavily_crawl(url, max_depth=None, max_pages=None, include_domains=None, exclude_domains=None, include_paths=None, exclude_paths=None, allow_external=None, respect_robots_txt=None, include_raw_content=None, workspace_id=None, **_extra):
    import json, os, datetime
    from urllib.parse import urlparse, urlunparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0256000" if __import__("os").path.isdir("./environment_mix/0256000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _is_str(x):
        return isinstance(x, str)

    def _is_bool(x):
        return isinstance(x, bool)

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _canonicalize(u):
        if not isinstance(u, str) or not u:
            return None
        try:
            p = urlparse(u)
        except Exception:
            return None
        if p.scheme not in ("http", "https") or not p.netloc:
            return None
        scheme = p.scheme.lower()
        netloc = p.netloc
        if "@" in netloc:
            netloc = netloc.split("@", 1)[1]
        host = netloc
        port = ""
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
        host = host.lower().strip(".")
        if port and ((scheme == "http" and port == "80") or (scheme == "https" and port == "443")):
            port = ""
        netloc2 = host + ((":" + port) if port else "")
        path = p.path or "/"
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        query = ""
        fragment = ""
        return urlunparse((scheme, netloc2, path, "", query, fragment))

    def _registrable_domain(hostname):
        if not hostname:
            return ""
        h = hostname.strip(".").lower()
        parts = [x for x in h.split(".") if x]
        if len(parts) <= 2:
            return h
        return ".".join(parts[-2:])

    def _sha256_hex(s):
        import hashlib
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        import secrets
        return prefix + secrets.token_hex(16)

    def _log_call(tool_calls, workspace_id_val, api_key_id_val, tool_name, status, requested_at, started_at=None, finished_at=None, expires_at=None, input_payload=None, normalized_input=None, error_code=None, error_message=None, estimated_tokens=None, billed_tokens=None):
        row_id = _gen_id("tav_call_")
        now = _now_iso()
        row = {
            "id": row_id,
            "workspace_id": workspace_id_val,
            "api_key_id": api_key_id_val,
            "tool_name": tool_name,
            "status": status,
            "requested_at": requested_at,
            "started_at": started_at,
            "finished_at": finished_at,
            "expires_at": expires_at,
            "input": input_payload if input_payload is not None else {},
            "normalized_input": normalized_input,
            "error_code": error_code,
            "error_message": error_message,
            "http_user_agent": None,
            "source_ip": None,
            "estimated_tokens": estimated_tokens,
            "billed_tokens": billed_tokens,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        return row

    def _upsert_web_resource(web_resources, canonical_url, robots_allowed=True, last_fetch_status=None, content_type=None, content_language=None, content_sha256=None, raw_content=None, clean_content=None, title=None):
        url_hash = _sha256_hex(canonical_url)
        now = _now_iso()
        existing = None
        for r in web_resources:
            if r.get("url_hash") == url_hash:
                existing = r
                break
        if existing is None:
            wr = {
                "id": _gen_id("tav_wr_"),
                "canonical_url": canonical_url,
                "url_hash": url_hash,
                "domain": _registrable_domain(urlparse(canonical_url).hostname or ""),
                "last_fetch_status": last_fetch_status,
                "last_fetched_at": now if last_fetch_status is not None else None,
                "content_type": content_type,
                "content_language": content_language,
                "content_sha256": content_sha256,
                "raw_content": raw_content if robots_allowed else None,
                "clean_content": clean_content if robots_allowed else None,
                "title": title,
                "robots_allowed": bool(robots_allowed),
                "created_at": now,
                "updated_at": now,
            }
            web_resources.append(wr)
            return wr, True
        # upsert metadata; do not create duplicates
        existing["canonical_url"] = canonical_url
        existing["domain"] = _registrable_domain(urlparse(canonical_url).hostname or "")
        if last_fetch_status is not None:
            existing["last_fetch_status"] = int(last_fetch_status)
            existing["last_fetched_at"] = now
        if content_type is not None:
            existing["content_type"] = content_type
        if content_language is not None:
            existing["content_language"] = content_language
        if title is not None:
            existing["title"] = title
        # robots policy
        existing["robots_allowed"] = bool(robots_allowed)
        if not existing["robots_allowed"]:
            existing["raw_content"] = None
            existing["clean_content"] = None
            existing["content_sha256"] = None
        else:
            if content_sha256 is not None:
                if isinstance(content_sha256, str) and len(content_sha256) == 64:
                    existing["content_sha256"] = content_sha256
            if raw_content is not None:
                existing["raw_content"] = raw_content
            if clean_content is not None:
                existing["clean_content"] = clean_content
        existing["updated_at"] = now
        return existing, False

    def _append_result(tool_call_results, tool_call_id, workspace_id_val, kind, rank=None, web_resource_id=None, from_web_resource_id=None, to_web_resource_id=None, payload=None):
        now = _now_iso()
        row = {
            "id": _gen_id("tav_res_"),
            "tool_call_id": tool_call_id,
            "workspace_id": workspace_id_val,
            "kind": kind,
            "rank": rank,
            "web_resource_id": web_resource_id,
            "from_web_resource_id": from_web_resource_id,
            "to_web_resource_id": to_web_resource_id,
            "payload": payload if isinstance(payload, dict) else {},
            "created_at": now,
            "updated_at": now,
        }
        tool_call_results.append(row)
        return row

    # ---- Load DB ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tool_calls = _load("tool_calls.json")
    web_resources = _load("web_resources.json")
    tool_call_results = _load("tool_call_results.json")

    # ---- Resolve workspace & ambient auth (no credential param in this tool) ----
    ws = None
    if workspace_id is not None:
        if not _is_str(workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id must be a string.")
        import re
        if not re.match(r"^tav_ws_01H[0-9A-Z]{15,}$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id does not match required pattern.")
        for w in workspaces:
            if w.get("id") == workspace_id:
                ws = w
                break
        if ws is None:
            return _err("NOT_FOUND", "workspace not found.")
    else:
        # pick any active workspace that can serve the call
        for w in workspaces:
            if w.get("status") == "active":
                ws = w
                break
        if ws is None:
            # no active workspaces at all
            requested_at = _now_iso()
            # can't attribute to a workspace; still avoid raising
            return _err("UNAUTHORIZED", "No active workspace available to serve this request.")

    # Choose an active API key in that workspace if any (for logging/last_used); tool supports internal/system too.
    api_key = None
    for k in api_keys:
        if k.get("workspace_id") == ws.get("id") and k.get("status") == "active":
            api_key = k
            break

    # ---- Validate inputs ----
    if not _is_str(url) or not url.strip():
        return _err("VALIDATION_ERROR", "url must be a non-empty string.")
    canon = _canonicalize(url.strip())
    if canon is None:
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URI with a host.")
    if max_depth is not None:
        if not _is_int(max_depth) or max_depth < 0 or max_depth > 10:
            return _err("VALIDATION_ERROR", "max_depth must be an integer between 0 and 10.")
    if max_pages is not None:
        if not _is_int(max_pages) or max_pages < 1 or max_pages > 1000:
            return _err("VALIDATION_ERROR", "max_pages must be an integer between 1 and 1000.")
    for arr, name in ((include_domains, "include_domains"), (exclude_domains, "exclude_domains"), (include_paths, "include_paths"), (exclude_paths, "exclude_paths")):
        if arr is not None:
            if not isinstance(arr, list) or any(not _is_str(x) for x in arr):
                return _err("VALIDATION_ERROR", f"{name} must be an array of strings.")
    if allow_external is not None and not _is_bool(allow_external):
        return _err("VALIDATION_ERROR", "allow_external must be a boolean.")
    if respect_robots_txt is not None and not _is_bool(respect_robots_txt):
        return _err("VALIDATION_ERROR", "respect_robots_txt must be a boolean.")
    if include_raw_content is not None and not _is_bool(include_raw_content):
        return _err("VALIDATION_ERROR", "include_raw_content must be a boolean.")

    # defaults
    max_depth_v = 2 if max_depth is None else max_depth
    max_pages_v = 50 if max_pages is None else max_pages
    allow_external_v = False if allow_external is None else allow_external
    respect_robots_txt_v = True if respect_robots_txt is None else respect_robots_txt
    include_raw_content_v = False if include_raw_content is None else include_raw_content

    # ---- Quota check before accepting ----
    if ws.get("status") != "active":
        # still record a tool_call row with failure
        requested_at = _now_iso()
        tc = _log_call(
            tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
            "tavily-crawl", "failed", requested_at,
            started_at=None, finished_at=_now_iso(),
            input_payload={
                "url": url, "max_depth": max_depth, "max_pages": max_pages,
                "include_domains": include_domains, "exclude_domains": exclude_domains,
                "include_paths": include_paths, "exclude_paths": exclude_paths,
                "allow_external": allow_external, "respect_robots_txt": respect_robots_txt,
                "include_raw_content": include_raw_content, "workspace_id": workspace_id
            },
            normalized_input={"canonical_base_url": canon, "max_depth": max_depth_v, "max_pages": max_pages_v},
            error_code="quota_exceeded",
            error_message="Workspace is not active.",
            estimated_tokens=None,
            billed_tokens=None
        )
        _save("tool_calls.json", tool_calls)
        return {
            "tool_call": tc,
            "results": [],
            "error": {"code": "QUOTA_EXCEEDED", "message": "quota_exceeded", "tool_call_id": tc["id"]},
        }

    now_dt = datetime.datetime.utcnow()
    usage_month = ws.get("usage_month")
    if not isinstance(usage_month, str) or usage_month != _month_key(now_dt):
        # rollover
        ws["usage_month"] = _month_key(now_dt)
        ws["requests_used_month"] = 0
        ws["tokens_used_month"] = 0
        ws["updated_at"] = _now_iso()

    if (ws.get("requests_used_month") is None) or (ws.get("monthly_request_limit") is None):
        return _err("VALIDATION_ERROR", "Workspace quota fields missing.")
    if int(ws.get("requests_used_month", 0)) + 1 > int(ws.get("monthly_request_limit", 0)):
        requested_at = _now_iso()
        tc = _log_call(
            tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
            "tavily-crawl", "failed", requested_at,
            started_at=None, finished_at=_now_iso(),
            input_payload={
                "url": url, "max_depth": max_depth, "max_pages": max_pages,
                "include_domains": include_domains, "exclude_domains": exclude_domains,
                "include_paths": include_paths, "exclude_paths": exclude_paths,
                "allow_external": allow_external, "respect_robots_txt": respect_robots_txt,
                "include_raw_content": include_raw_content, "workspace_id": workspace_id
            },
            normalized_input={"canonical_base_url": canon, "max_depth": max_depth_v, "max_pages": max_pages_v},
            error_code="quota_exceeded",
            error_message="Monthly request limit exceeded.",
            estimated_tokens=None,
            billed_tokens=None
        )
        _save("tool_calls.json", tool_calls)
        return {
            "tool_call": tc,
            "results": [],
            "error": {"code": "QUOTA_EXCEEDED", "message": "quota_exceeded", "tool_call_id": tc["id"]},
        }

    # token estimate check for crawl/map/extract
    estimated_tokens = max(1, int(max_pages_v) * 50 + int(max_depth_v) * 10)
    if int(ws.get("tokens_used_month", 0)) + estimated_tokens > int(ws.get("monthly_token_limit", 0)):
        requested_at = _now_iso()
        tc = _log_call(
            tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
            "tavily-crawl", "failed", requested_at,
            started_at=None, finished_at=_now_iso(),
            input_payload={
                "url": url, "max_depth": max_depth, "max_pages": max_pages,
                "include_domains": include_domains, "exclude_domains": exclude_domains,
                "include_paths": include_paths, "exclude_paths": exclude_paths,
                "allow_external": allow_external, "respect_robots_txt": respect_robots_txt,
                "include_raw_content": include_raw_content, "workspace_id": workspace_id
            },
            normalized_input={"canonical_base_url": canon, "max_depth": max_depth_v, "max_pages": max_pages_v},
            error_code="quota_exceeded",
            error_message="Monthly token limit exceeded.",
            estimated_tokens=estimated_tokens,
            billed_tokens=None
        )
        _save("tool_calls.json", tool_calls)
        return {
            "tool_call": tc,
            "results": [],
            "error": {"code": "QUOTA_EXCEEDED", "message": "quota_exceeded", "tool_call_id": tc["id"]},
        }

    # ---- Create tool call row (queued) ----
    requested_at = _now_iso()
    input_payload = {
        "url": url,
        "max_depth": max_depth,
        "max_pages": max_pages,
        "include_domains": include_domains,
        "exclude_domains": exclude_domains,
        "include_paths": include_paths,
        "exclude_paths": exclude_paths,
        "allow_external": allow_external,
        "respect_robots_txt": respect_robots_txt,
        "include_raw_content": include_raw_content,
        "workspace_id": workspace_id,
    }
    normalized_input = {
        "canonical_base_url": canon,
        "max_depth": max_depth_v,
        "max_pages": max_pages_v,
        "allow_external": allow_external_v,
        "respect_robots_txt": respect_robots_txt_v,
        "include_raw_content": include_raw_content_v,
        "include_domains": include_domains or None,
        "exclude_domains": exclude_domains or None,
        "include_paths": include_paths or None,
        "exclude_paths": exclude_paths or None,
    }
    tc = _log_call(
        tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
        "tavily-crawl", "queued", requested_at,
        normalized_input=normalized_input,
        input_payload=input_payload,
        estimated_tokens=estimated_tokens
    )

    # Transition queued -> running (legal)
    tc["status"] = "running"
    tc["started_at"] = _now_iso()
    tc["updated_at"] = _now_iso()
    if api_key is not None:
        api_key["last_used_at"] = _now_iso()
        api_key["updated_at"] = _now_iso()

    # ---- Perform a lightweight offline "crawl" (no network): store base URL as a visited page ----
    base_host = urlparse(canon).hostname or ""
    base_domain = _registrable_domain(base_host)

    def _domain_allowed(domain):
        d = (domain or "").lower()
        if exclude_domains:
            for ex in exclude_domains:
                if d == ex.lower() or d.endswith("." + ex.lower()):
                    return False
        if include_domains:
            ok = False
            for inc in include_domains:
                inc2 = inc.lower()
                if d == inc2 or d.endswith("." + inc2):
                    ok = True
                    break
            if not ok:
                return False
        return True

    def _path_allowed(path):
        p = path or "/"
        if exclude_paths:
            for ex in exclude_paths:
                if p.startswith(ex):
                    return False
        if include_paths:
            ok = any(p.startswith(inc) for inc in include_paths)
            if not ok:
                return False
        return True

    robots_allowed = True
    if respect_robots_txt_v:
        # offline policy: default allow; if existing web_resource marks robots_allowed False, keep it
        pass

    # Upsert base web_resource
    wr, _created = _upsert_web_resource(
        web_resources,
        canon,
        robots_allowed=robots_allowed,
        last_fetch_status=200,
        content_type="text/html; charset=utf-8",
        content_language=None,
        content_sha256=None,
        raw_content=("" if include_raw_content_v else None),
        clean_content=None,
        title=None
    )

    results_emitted = []
    if not _domain_allowed(urlparse(canon).hostname or "") or not _path_allowed(urlparse(canon).path or "/"):
        tc["status"] = "failed"
        tc["error_code"] = "invalid_url"
        tc["error_message"] = "Base URL is excluded by include/exclude rules."
    else:
        # if robots disallowed at time of fetch, fail per policy
        if wr.get("robots_allowed") is False and respect_robots_txt_v:
            tc["status"] = "failed"
            tc["error_code"] = "robots_disallowed"
            tc["error_message"] = "Robots policy disallows crawling this URL."
        else:
            # emit one crawl_page result for base
            res = _append_result(
                tool_call_results,
                tc["id"],
                ws["id"],
                "crawl_page",
                rank=1,
                web_resource_id=wr["id"],
                payload={
                    "url": canon,
                    "domain": base_domain,
                    "depth": 0,
                    "status_code": 200,
                    "allow_external": allow_external_v,
                    "respect_robots_txt": respect_robots_txt_v,
                    "note": "Offline crawl: only base URL recorded."
                }
            )
            results_emitted.append(res)
            tc["status"] = "succeeded"

    # Transition running -> terminal with finished_at
    tc["finished_at"] = _now_iso()
    tc["updated_at"] = _now_iso()

    # ---- Billing: only on success ----
    if tc["status"] == "succeeded":
        billed_tokens = max(1, int(estimated_tokens))
        tc["billed_tokens"] = billed_tokens
        # atomic-ish in single-file store: update workspace counters before saving
        ws["requests_used_month"] = int(ws.get("requests_used_month", 0)) + 1
        ws["tokens_used_month"] = int(ws.get("tokens_used_month", 0)) + int(billed_tokens)
        ws["updated_at"] = _now_iso()

    # ---- Persist ----
    _save("workspaces.json", workspaces)
    _save("api_keys.json", api_keys)
    _save("tool_calls.json", tool_calls)
    _save("web_resources.json", web_resources)
    _save("tool_call_results.json", tool_call_results)

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {
        "tool_call": tc,
        "initial_metadata": {
            "canonical_base_url": canon,
            "max_depth": max_depth_v,
            "max_pages": max_pages_v,
            "estimated_tokens": estimated_tokens,
            "billed_tokens": tc.get("billed_tokens"),
            "latency_ms": latency_ms,
        },
        "results": results_emitted,
    }

def tavily_map(url, max_depth=None, max_urls=None, include_domains=None, exclude_domains=None, include_paths=None, exclude_paths=None, respect_robots_txt=None, workspace_id=None, **_extra):
    import json, os, datetime
    from urllib.parse import urlparse, urlunparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0256000" if __import__("os").path.isdir("./environment_mix/0256000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _is_str(x):
        return isinstance(x, str)

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _is_bool(x):
        return isinstance(x, bool)

    def _canonicalize(u):
        if not isinstance(u, str) or not u:
            return None
        try:
            p = urlparse(u)
        except Exception:
            return None
        if p.scheme not in ("http", "https") or not p.netloc:
            return None
        scheme = p.scheme.lower()
        netloc = p.netloc
        if "@" in netloc:
            netloc = netloc.split("@", 1)[1]
        host = netloc
        port = ""
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
        host = host.lower().strip(".")
        if port and ((scheme == "http" and port == "80") or (scheme == "https" and port == "443")):
            port = ""
        netloc2 = host + ((":" + port) if port else "")
        path = p.path or "/"
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        query = ""
        fragment = ""
        return urlunparse((scheme, netloc2, path, "", query, fragment))

    def _registrable_domain(hostname):
        if not hostname:
            return ""
        h = hostname.strip(".").lower()
        parts = [x for x in h.split(".") if x]
        if len(parts) <= 2:
            return h
        return ".".join(parts[-2:])

    def _sha256_hex(s):
        import hashlib
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        import secrets
        return prefix + secrets.token_hex(16)

    def _log_call(tool_calls, workspace_id_val, api_key_id_val, tool_name, status, requested_at, started_at=None, finished_at=None, expires_at=None, input_payload=None, normalized_input=None, error_code=None, error_message=None, estimated_tokens=None, billed_tokens=None):
        row_id = _gen_id("tav_call_")
        now = _now_iso()
        row = {
            "id": row_id,
            "workspace_id": workspace_id_val,
            "api_key_id": api_key_id_val,
            "tool_name": tool_name,
            "status": status,
            "requested_at": requested_at,
            "started_at": started_at,
            "finished_at": finished_at,
            "expires_at": expires_at,
            "input": input_payload if input_payload is not None else {},
            "normalized_input": normalized_input,
            "error_code": error_code,
            "error_message": error_message,
            "http_user_agent": None,
            "source_ip": None,
            "estimated_tokens": estimated_tokens,
            "billed_tokens": billed_tokens,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        return row

    def _upsert_web_resource(web_resources, canonical_url, robots_allowed=True, last_fetch_status=None, title=None):
        url_hash = _sha256_hex(canonical_url)
        now = _now_iso()
        existing = None
        for r in web_resources:
            if r.get("url_hash") == url_hash:
                existing = r
                break
        if existing is None:
            wr = {
                "id": _gen_id("tav_wr_"),
                "canonical_url": canonical_url,
                "url_hash": url_hash,
                "domain": _registrable_domain(urlparse(canonical_url).hostname or ""),
                "last_fetch_status": last_fetch_status,
                "last_fetched_at": now if last_fetch_status is not None else None,
                "content_type": None,
                "content_language": None,
                "content_sha256": None,
                "raw_content": None,
                "clean_content": None,
                "title": title,
                "robots_allowed": bool(robots_allowed),
                "created_at": now,
                "updated_at": now,
            }
            web_resources.append(wr)
            return wr, True
        existing["canonical_url"] = canonical_url
        existing["domain"] = _registrable_domain(urlparse(canonical_url).hostname or "")
        if last_fetch_status is not None:
            existing["last_fetch_status"] = int(last_fetch_status)
            existing["last_fetched_at"] = now
        if title is not None:
            existing["title"] = title
        existing["robots_allowed"] = bool(robots_allowed)
        if not existing["robots_allowed"]:
            existing["raw_content"] = None
            existing["clean_content"] = None
            existing["content_sha256"] = None
        existing["updated_at"] = now
        return existing, False

    def _append_result(tool_call_results, tool_call_id, workspace_id_val, kind, rank=None, web_resource_id=None, from_web_resource_id=None, to_web_resource_id=None, payload=None):
        now = _now_iso()
        row = {
            "id": _gen_id("tav_res_"),
            "tool_call_id": tool_call_id,
            "workspace_id": workspace_id_val,
            "kind": kind,
            "rank": rank,
            "web_resource_id": web_resource_id,
            "from_web_resource_id": from_web_resource_id,
            "to_web_resource_id": to_web_resource_id,
            "payload": payload if isinstance(payload, dict) else {},
            "created_at": now,
            "updated_at": now,
        }
        tool_call_results.append(row)
        return row

    # ---- Load DB ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tool_calls = _load("tool_calls.json")
    web_resources = _load("web_resources.json")
    tool_call_results = _load("tool_call_results.json")

    # ---- Resolve workspace (ambient) ----
    ws = None
    if workspace_id is not None:
        if not _is_str(workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id must be a string.")
        import re
        if not re.match(r"^tav_ws_01H[0-9A-Z]{15,}$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id does not match required pattern.")
        for w in workspaces:
            if w.get("id") == workspace_id:
                ws = w
                break
        if ws is None:
            return _err("NOT_FOUND", "workspace not found.")
    else:
        for w in workspaces:
            if w.get("status") == "active":
                ws = w
                break
        if ws is None:
            return _err("UNAUTHORIZED", "No active workspace available to serve this request.")

    api_key = None
    for k in api_keys:
        if k.get("workspace_id") == ws.get("id") and k.get("status") == "active":
            api_key = k
            break

    # ---- Validate inputs ----
    if not _is_str(url) or not url.strip():
        return _err("VALIDATION_ERROR", "url must be a non-empty string.")
    canon = _canonicalize(url.strip())
    if canon is None:
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URI with a host.")
    if max_depth is not None:
        if not _is_int(max_depth) or max_depth < 0 or max_depth > 10:
            return _err("VALIDATION_ERROR", "max_depth must be an integer between 0 and 10.")
    if max_urls is not None:
        if not _is_int(max_urls) or max_urls < 1 or max_urls > 5000:
            return _err("VALIDATION_ERROR", "max_urls must be an integer between 1 and 5000.")
    for arr, name in ((include_domains, "include_domains"), (exclude_domains, "exclude_domains"), (include_paths, "include_paths"), (exclude_paths, "exclude_paths")):
        if arr is not None:
            if not isinstance(arr, list) or any(not _is_str(x) for x in arr):
                return _err("VALIDATION_ERROR", f"{name} must be an array of strings.")
    if respect_robots_txt is not None and not _is_bool(respect_robots_txt):
        return _err("VALIDATION_ERROR", "respect_robots_txt must be a boolean.")

    max_depth_v = 2 if max_depth is None else max_depth
    max_urls_v = 200 if max_urls is None else max_urls
    respect_robots_txt_v = True if respect_robots_txt is None else respect_robots_txt

    # ---- Quota checks ----
    if ws.get("status") != "active":
        requested_at = _now_iso()
        tc = _log_call(
            tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
            "tavily-map", "failed", requested_at,
            finished_at=_now_iso(),
            input_payload={
                "url": url, "max_depth": max_depth, "max_urls": max_urls,
                "include_domains": include_domains, "exclude_domains": exclude_domains,
                "include_paths": include_paths, "exclude_paths": exclude_paths,
                "respect_robots_txt": respect_robots_txt, "workspace_id": workspace_id
            },
            normalized_input={"canonical_base_url": canon, "max_depth": max_depth_v, "max_urls": max_urls_v},
            error_code="quota_exceeded",
            error_message="Workspace is not active."
        )
        _save("tool_calls.json", tool_calls)
        return {
            "tool_call": tc,
            "results": [],
            "error": {"code": "QUOTA_EXCEEDED", "message": "quota_exceeded", "tool_call_id": tc["id"]},
        }

    now_dt = datetime.datetime.utcnow()
    usage_month = ws.get("usage_month")
    if not isinstance(usage_month, str) or usage_month != _month_key(now_dt):
        ws["usage_month"] = _month_key(now_dt)
        ws["requests_used_month"] = 0
        ws["tokens_used_month"] = 0
        ws["updated_at"] = _now_iso()

    if int(ws.get("requests_used_month", 0)) + 1 > int(ws.get("monthly_request_limit", 0)):
        requested_at = _now_iso()
        tc = _log_call(
            tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
            "tavily-map", "failed", requested_at,
            finished_at=_now_iso(),
            input_payload={
                "url": url, "max_depth": max_depth, "max_urls": max_urls,
                "include_domains": include_domains, "exclude_domains": exclude_domains,
                "include_paths": include_paths, "exclude_paths": exclude_paths,
                "respect_robots_txt": respect_robots_txt, "workspace_id": workspace_id
            },
            normalized_input={"canonical_base_url": canon, "max_depth": max_depth_v, "max_urls": max_urls_v},
            error_code="quota_exceeded",
            error_message="Monthly request limit exceeded."
        )
        _save("tool_calls.json", tool_calls)
        return {
            "tool_call": tc,
            "results": [],
            "error": {"code": "QUOTA_EXCEEDED", "message": "quota_exceeded", "tool_call_id": tc["id"]},
        }

    estimated_tokens = max(1, int(max_urls_v) * 5 + int(max_depth_v) * 10)
    if int(ws.get("tokens_used_month", 0)) + estimated_tokens > int(ws.get("monthly_token_limit", 0)):
        requested_at = _now_iso()
        tc = _log_call(
            tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
            "tavily-map", "failed", requested_at,
            finished_at=_now_iso(),
            input_payload={
                "url": url, "max_depth": max_depth, "max_urls": max_urls,
                "include_domains": include_domains, "exclude_domains": exclude_domains,
                "include_paths": include_paths, "exclude_paths": exclude_paths,
                "respect_robots_txt": respect_robots_txt, "workspace_id": workspace_id
            },
            normalized_input={"canonical_base_url": canon, "max_depth": max_depth_v, "max_urls": max_urls_v},
            error_code="quota_exceeded",
            error_message="Monthly token limit exceeded.",
            estimated_tokens=estimated_tokens
        )
        _save("tool_calls.json", tool_calls)
        return {
            "tool_call": tc,
            "results": [],
            "error": {"code": "QUOTA_EXCEEDED", "message": "quota_exceeded", "tool_call_id": tc["id"]},
        }

    # ---- Create tool call queued -> running ----
    requested_at = _now_iso()
    input_payload = {
        "url": url,
        "max_depth": max_depth,
        "max_urls": max_urls,
        "include_domains": include_domains,
        "exclude_domains": exclude_domains,
        "include_paths": include_paths,
        "exclude_paths": exclude_paths,
        "respect_robots_txt": respect_robots_txt,
        "workspace_id": workspace_id,
    }
    normalized_input = {
        "canonical_base_url": canon,
        "max_depth": max_depth_v,
        "max_urls": max_urls_v,
        "respect_robots_txt": respect_robots_txt_v,
        "include_domains": include_domains or None,
        "exclude_domains": exclude_domains or None,
        "include_paths": include_paths or None,
        "exclude_paths": exclude_paths or None,
    }
    tc = _log_call(
        tool_calls, ws.get("id"), (api_key.get("id") if api_key else None),
        "tavily-map", "queued", requested_at,
        input_payload=input_payload,
        normalized_input=normalized_input,
        estimated_tokens=estimated_tokens
    )
    tc["status"] = "running"
    tc["started_at"] = _now_iso()
    tc["updated_at"] = _now_iso()
    if api_key is not None:
        api_key["last_used_at"] = _now_iso()
        api_key["updated_at"] = _now_iso()

    # ---- Offline mapping: create a single node for base URL; no edges ----
    base_p = urlparse(canon)
    base_host = base_p.hostname or ""
    base_domain = _registrable_domain(base_host)

    def _domain_allowed(hostname):
        d = (hostname or "").lower()
        if exclude_domains:
            for ex in exclude_domains:
                ex2 = ex.lower()
                if d == ex2 or d.endswith("." + ex2):
                    return False
        if include_domains:
            ok = False
            for inc in include_domains:
                inc2 = inc.lower()
                if d == inc2 or d.endswith("." + inc2):
                    ok = True
                    break
            if not ok:
                return False
        return True

    def _path_allowed(path):
        p = path or "/"
        if exclude_paths:
            for ex in exclude_paths:
                if p.startswith(ex):
                    return False
        if include_paths:
            ok = any(p.startswith(inc) for inc in include_paths)
            if not ok:
                return False
        return True

    results_emitted = []
    if not _domain_allowed(base_host) or not _path_allowed(base_p.path or "/"):
        tc["status"] = "failed"
        tc["error_code"] = "invalid_url"
        tc["error_message"] = "Base URL is excluded by include/exclude rules."
    else:
        # if existing web_resource says robots disallowed and we respect robots, fail
        # (offline: no robots fetch; rely on stored policy)
        wr, _created = _upsert_web_resource(web_resources, canon, robots_allowed=True, last_fetch_status=None, title=None)
        if respect_robots_txt_v and wr.get("robots_allowed") is False:
            tc["status"] = "failed"
            tc["error_code"] = "robots_disallowed"
            tc["error_message"] = "Robots policy disallows mapping this URL."
        else:
            node = _append_result(
                tool_call_results,
                tc["id"],
                ws["id"],
                "map_node",
                rank=1,
                web_resource_id=wr["id"],
                payload={"url": canon, "domain": base_domain, "depth": 0, "note": "Offline map: only base node recorded."}
            )
            results_emitted.append(node)
            tc["status"] = "succeeded"

    tc["finished_at"] = _now_iso()
    tc["updated_at"] = _now_iso()

    if tc["status"] == "succeeded":
        billed_tokens = max(1, int(estimated_tokens))
        tc["billed_tokens"] = billed_tokens
        ws["requests_used_month"] = int(ws.get("requests_used_month", 0)) + 1
        ws["tokens_used_month"] = int(ws.get("tokens_used_month", 0)) + int(billed_tokens)
        ws["updated_at"] = _now_iso()

    _save("workspaces.json", workspaces)
    _save("api_keys.json", api_keys)
    _save("tool_calls.json", tool_calls)
    _save("web_resources.json", web_resources)
    _save("tool_call_results.json", tool_call_results)

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {
        "tool_call": tc,
        "initial_metadata": {
            "canonical_base_url": canon,
            "max_depth": max_depth_v,
            "max_urls": max_urls_v,
            "estimated_tokens": estimated_tokens,
            "billed_tokens": tc.get("billed_tokens"),
            "latency_ms": latency_ms,
        },
        "results": results_emitted,
    }

def tavily_whoami(api_key, workspace_id=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0256000" if __import__("os").path.isdir("./environment_mix/0256000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _month_key(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return f"{dt.year:04d}-{dt.month:02d}"

    def _coerce_current_month(ws, now):
        mk = _month_key(now)
        if ws.get("usage_month") != mk:
            ws["usage_month"] = mk
            ws["requests_used_month"] = 0
            ws["tokens_used_month"] = 0
            return True
