def tavily_tool_calls_list(api_key=None, workspace_id=None, tool_name=None, status=None, from_requested_at=None, to_requested_at=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0256000" if __import__("os").path.isdir("./environment_mix/0256000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "TYPE_ERROR"
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return "PARSE_ERROR"
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _enc_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _dec_cursor(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return "TYPE_ERROR"
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return "PARSE_ERROR"

    def _gen_id(prefix, now):
        h = hashlib.sha256(f"{prefix}:{now.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20]
        return f"{prefix}_01H{h.upper()[:16]}"

    def _find_api_key_row(api_key_value, api_keys):
        v = api_key_value.strip()
        for r in api_keys:
            if isinstance(r, dict) and r.get("id") == v:
                return r
        for r in api_keys:
            if isinstance(r, dict) and isinstance(r.get("key_prefix"), str) and r.get("key_prefix") and v.startswith(r["key_prefix"]):
                return r
        return None

    def _record_request_log(now, ws_id, api_key_id, ok, error_code=None, error_message=None, normalized_input=None):
        tool_calls = _load("tool_calls.json")
        ts = _iso(now)
        row = {
            "id": _gen_id("tav_call", now),
            "workspace_id": ws_id if isinstance(ws_id, str) and ws_id else "tav_ws_unknown",
            "api_key_id": api_key_id,
            "tool_name": "tavily-search",
            "status": "succeeded" if ok else "failed",
            "requested_at": ts,
            "started_at": ts,
            "finished_at": ts,
            "expires_at": None,
            "input": {
                "endpoint": "tavily-tool-calls-list",
                "workspace_id": workspace_id,
                "tool_name": tool_name,
                "status": status,
                "from_requested_at": from_requested_at,
                "to_requested_at": to_requested_at,
                "limit": limit,
                "cursor": cursor,
            },
            "normalized_input": normalized_input,
            "error_code": error_code,
            "error_message": error_message,
            "http_user_agent": None,
            "source_ip": None,
            "estimated_tokens": 0,
            "billed_tokens": 0,
            "created_at": ts,
            "updated_at": ts,
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    t0 = time.time()
    now = _utcnow()

    ALLOWED_TOOL_NAMES = {"tavily-search", "tavily-extract", "tavily-crawl", "tavily-map"}
    ALLOWED_STATUS = {"queued", "running", "succeeded", "failed", "cancelled", "expired"}

    # Validate (must not raise if called without required args in some environments)
    if not isinstance(api_key, str) or not api_key.strip():
        _record_request_log(now, None, None, False, "validation_error", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(workspace_id, str) or not re.match(r"^tav_ws_01H[0-9A-Z]{15,}$", workspace_id):
        _record_request_log(now, None, None, False, "validation_error", "workspace_id does not match required pattern")
        return _err("VALIDATION_ERROR", "workspace_id does not match required pattern")

    if tool_name is not None and tool_name not in ALLOWED_TOOL_NAMES:
        _record_request_log(now, workspace_id, None, False, "validation_error", "tool_name must be one of the allowed values")
        return _err("VALIDATION_ERROR", "tool_name must be one of the allowed values")
    if status is not None and status not in ALLOWED_STATUS:
        _record_request_log(now, workspace_id, None, False, "validation_error", "status must be one of the allowed values")
        return _err("VALIDATION_ERROR", "status must be one of the allowed values")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record_request_log(now, workspace_id, None, False, "validation_error", "limit must be an integer between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    dt_from = _parse_rfc3339(from_requested_at)
    if dt_from in ("TYPE_ERROR", "PARSE_ERROR"):
        _record_request_log(now, workspace_id, None, False, "validation_error", "from_requested_at must be an RFC3339 timestamp")
        return _err("VALIDATION_ERROR", "from_requested_at must be an RFC3339 timestamp")
    dt_to = _parse_rfc3339(to_requested_at)
    if dt_to in ("TYPE_ERROR", "PARSE_ERROR"):
        _record_request_log(now, workspace_id, None, False, "validation_error", "to_requested_at must be an RFC3339 timestamp")
        return _err("VALIDATION_ERROR", "to_requested_at must be an RFC3339 timestamp")

    if dt_from and dt_to and dt_to < dt_from:
        _record_request_log(now, workspace_id, None, False, "validation_error", "to_requested_at must be >= from_requested_at")
        return _err("VALIDATION_ERROR", "to_requested_at must be >= from_requested_at")

    api_keys = _load("api_keys.json")
    key_row = _find_api_key_row(api_key, api_keys)
    if not key_row or key_row.get("status") != "active":
        _record_request_log(now, workspace_id, None, False, "unauthorized", "Invalid or revoked API key")
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    if key_row.get("workspace_id") != workspace_id:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "unauthorized", "API key does not belong to workspace")
        return _err("UNAUTHORIZED", "API key does not belong to workspace")

    # Workspace must exist and be active for this endpoint
    workspaces = _load("workspaces.json")
    ws_row = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws_row = w
            break
    if not ws_row:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "not_found", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if ws_row.get("status") != "active":
        _record_request_log(now, workspace_id, key_row.get("id"), False, "unauthorized", "Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Update last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    decoded = _dec_cursor(cursor)
    if decoded == "TYPE_ERROR" or decoded == "PARSE_ERROR":
        _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "cursor is invalid")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    after = None
    if isinstance(decoded, dict):
        after = decoded.get("after")  # requested_at cursor

    tool_calls = _load("tool_calls.json")
    rows = []
    for r in tool_calls:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        ra = r.get("requested_at")
        dtra = _parse_rfc3339(ra) if isinstance(ra, str) else None
        if dt_from and dtra and dtra < dt_from:
            continue
        if dt_to and dtra and dtra > dt_to:
            continue
        rows.append(r)

    def _key(r):
        ra = r.get("requested_at") or ""
        return (ra, r.get("id") or "")

    rows.sort(key=_key, reverse=True)

    if after:
        # after is {requested_at, id}
        try:
            a_ra = after.get("requested_at")
            a_id = after.get("id")
        except Exception:
            a_ra, a_id = None, None
        if isinstance(a_ra, str) and isinstance(a_id, str):
            filtered = []
            for r in rows:
                if (r.get("requested_at"), r.get("id")) < (a_ra, a_id):
                    filtered.append(r)
            rows = filtered

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _enc_cursor({"after": {"requested_at": last.get("requested_at"), "id": last.get("id")}})

    _record_request_log(
        now,
        workspace_id,
        key_row.get("id"),
        True,
        normalized_input={
            "resolved_workspace_id": workspace_id,
            "tool_name": tool_name,
            "status": status,
            "from_requested_at": from_requested_at,
            "to_requested_at": to_requested_at,
            "limit": limit,
        },
    )

    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

