            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _enc_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _dec_cursor(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return "TYPE_ERROR"
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return "PARSE_ERROR"

    def _gen_id(prefix, now):
        h = hashlib.sha256(f"{prefix}:{now.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20]
        return f"{prefix}_01H{h.upper()[:16]}"

    def _find_api_key_row(api_key_value, api_keys):
        v = api_key_value.strip()
        for r in api_keys:
            if isinstance(r, dict) and r.get("id") == v:
                return r
        for r in api_keys:
            if isinstance(r, dict) and isinstance(r.get("key_prefix"), str) and r.get("key_prefix") and v.startswith(r["key_prefix"]):
                return r
        return None

    def _record_request_log(now, ws_id, api_key_id, ok, error_code=None, error_message=None, normalized_input=None):
        tool_calls = _load("tool_calls.json")
        ts = _iso(now)
        row = {
            "id": _gen_id("tav_call", now),
            "workspace_id": ws_id if isinstance(ws_id, str) and ws_id else "tav_ws_unknown",
            "api_key_id": api_key_id,
            "tool_name": "tavily-search",
            "status": "succeeded" if ok else "failed",
            "requested_at": ts,
            "started_at": ts,
            "finished_at": ts,
            "expires_at": None,
            "input": {"endpoint": "tavily-tool-call-results-list", "workspace_id": workspace_id, "tool_call_id": tool_call_id, "kind": kind, "limit": limit, "cursor": cursor},
            "normalized_input": normalized_input,
            "error_code": error_code,
            "error_message": error_message,
            "http_user_agent": None,
            "source_ip": None,
            "estimated_tokens": 0,
            "billed_tokens": 0,
            "created_at": ts,
            "updated_at": ts,
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    t0 = time.time()
    now = _utcnow()

    ALLOWED_KIND = {"search_hit", "extracted_document", "crawl_page", "map_node", "map_edge"}

    if not isinstance(api_key, str) or not api_key.strip():
        _record_request_log(now, None, None, False, "validation_error", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(workspace_id, str) or not re.match(r"^tav_ws_01H[0-9A-Z]{15,}$", workspace_id):
        _record_request_log(now, None, None, False, "validation_error", "workspace_id does not match required pattern")
        return _err("VALIDATION_ERROR", "workspace_id does not match required pattern")
    if not isinstance(tool_call_id, str) or not tool_call_id.strip():
        _record_request_log(now, workspace_id, None, False, "validation_error", "tool_call_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "tool_call_id must be a non-empty string")
    if kind is not None and kind not in ALLOWED_KIND:
        _record_request_log(now, workspace_id, None, False, "validation_error", "kind must be one of the allowed values")
        return _err("VALIDATION_ERROR", "kind must be one of the allowed values")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _record_request_log(now, workspace_id, None, False, "validation_error", "limit must be an integer between 1 and 500")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

    api_keys = _load("api_keys.json")
    key_row = _find_api_key_row(api_key, api_keys)
    if not key_row or key_row.get("status") != "active":
        _record_request_log(now, workspace_id, None, False, "unauthorized", "Invalid or revoked API key")
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    if key_row.get("workspace_id") != workspace_id:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "unauthorized", "API key does not belong to workspace")
        return _err("UNAUTHORIZED", "API key does not belong to workspace")

    # Update last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # Ensure tool_call belongs to workspace
    tool_calls = _load("tool_calls.json")
    call_row = None
    for r in tool_calls:
        if isinstance(r, dict) and r.get("id") == tool_call_id:
            call_row = r
            break
    if not call_row:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "not_found", "Tool call not found")
        return _err("NOT_FOUND", "Tool call not found")
    if call_row.get("workspace_id") != workspace_id:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "unauthorized", "Tool call does not belong to workspace")
        return _err("UNAUTHORIZED", "Tool call does not belong to workspace")

    decoded = _dec_cursor(cursor)
    if decoded in ("TYPE_ERROR", "PARSE_ERROR"):
        _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "cursor is invalid")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    after = None
    if isinstance(decoded, dict):
        after = decoded.get("after")  # {kind, rank, created_at, id}

    results = _load("tool_call_results.json")
    rows = []
    for r in results:
        if not isinstance(r, dict):
            continue
        if r.get("tool_call_id") != tool_call_id:
            continue
        # Enforce denormalized workspace consistency while reading; do not error, just filter.
        if r.get("workspace_id") != workspace_id:
            continue
        if kind is not None and r.get("kind") != kind:
            continue
        rows.append(r)

    def _rank_key(v):
        rk = v.get("rank")
        if isinstance(rk, int):
            return rk
        return 10**12

    def _sort_key(r):
        return (r.get("kind") or "", _rank_key(r), r.get("created_at") or "", r.get("id") or "")

    rows.sort(key=_sort_key)

    if isinstance(after, dict):
        a_kind = after.get("kind")
        a_rank = after.get("rank")
        a_created = after.get("created_at")
        a_id = after.get("id")
        if isinstance(a_kind, str) and isinstance(a_created, str) and isinstance(a_id, str):
            try:
                a_rank_norm = a_rank if isinstance(a_rank, int) else 10**12
                filtered = []
                for r in rows:
                    if _sort_key(r) > (a_kind, a_rank_norm, a_created, a_id):
                        filtered.append(r)
                rows = filtered
            except Exception:
                # If cursor shape is unexpected, treat as validation error rather than silently misbehaving.
                _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "cursor is invalid")
                return _err("VALIDATION_ERROR", "cursor is invalid")

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _enc_cursor(
            {
                "after": {
                    "kind": last.get("kind"),
                    "rank": last.get("rank"),
                    "created_at": last.get("created_at"),
                    "id": last.get("id"),
                }
            }
        )

    _record_request_log(now, workspace_id, key_row.get("id"), True, normalized_input={"resolved_workspace_id": workspace_id, "kind": kind, "limit": limit})
    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def tavily_tool_calls_update(api_key, workspace_id, tool_call_id, status=None, error_code=None, error_message=None, started_at=None, finished_at=None, expires_at=None, billed_tokens=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0256000" if __import__("os").path.isdir("./environment_mix/0256000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _utcnow()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "TYPE_ERROR"
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return "PARSE_ERROR"
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _month_key(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return f"{dt.year:04d}-{dt.month:02d}"

    def _coerce_current_month(ws, now):
        mk = _month_key(now)
        if ws.get("usage_month") != mk:
            ws["usage_month"] = mk
            ws["requests_used_month"] = 0
            ws["tokens_used_month"] = 0
            return True
        return False

    def _gen_id(prefix, now):
        h = hashlib.sha256(f"{prefix}:{now.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20]
        return f"{prefix}_01H{h.upper()[:16]}"

    def _find_api_key_row(api_key_value, api_keys):
        v = api_key_value.strip()
        for r in api_keys:
            if isinstance(r, dict) and r.get("id") == v:
                return r
        for r in api_keys:
            if isinstance(r, dict) and isinstance(r.get("key_prefix"), str) and r.get("key_prefix") and v.startswith(r["key_prefix"]):
                return r
        return None

    def _record_request_log(now, ws_id, api_key_id, ok, error_code_log=None, error_message_log=None, normalized_input=None):
        tool_calls = _load("tool_calls.json")
        ts = _iso(now)
        row = {
            "id": _gen_id("tav_call", now),
            "workspace_id": ws_id if isinstance(ws_id, str) and ws_id else "tav_ws_unknown",
            "api_key_id": api_key_id,
            "tool_name": "tavily-search",
            "status": "succeeded" if ok else "failed",
            "requested_at": ts,
            "started_at": ts,
            "finished_at": ts,
            "expires_at": None,
            "input": {
                "endpoint": "tavily-tool-calls-update",
                "workspace_id": workspace_id,
                "tool_call_id": tool_call_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "started_at": started_at,
                "finished_at": finished_at,
                "expires_at": expires_at,
                "billed_tokens": billed_tokens,
            },
            "normalized_input": normalized_input,
            "error_code": error_code_log,
            "error_message": error_message_log,
            "http_user_agent": None,
            "source_ip": None,
            "estimated_tokens": 0,
            "billed_tokens": 0,
            "created_at": ts,
            "updated_at": ts,
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    now = _utcnow()

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled", "expired"}
    transitions = {
        "queued": {"running", "cancelled", "failed", "expired"},
        "running": {"succeeded", "failed", "cancelled", "expired"},
        "succeeded": {"expired"},
        "failed": {"expired"},
        "cancelled": {"expired"},
        "expired": set(),
    }
    allowed_error_code = {"quota_exceeded", "robots_disallowed", "validation_error", "fetch_failed", "timeout", "cancelled", "internal_error"}

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _record_request_log(now, None, None, False, "validation_error", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(workspace_id, str) or not re.match(r"^tav_ws_01H[0-9A-Z]{15,}$", workspace_id):
        _record_request_log(now, None, None, False, "validation_error", "workspace_id does not match required pattern")
        return _err("VALIDATION_ERROR", "workspace_id does not match required pattern")
    if not isinstance(tool_call_id, str) or not tool_call_id.strip():
        _record_request_log(now, workspace_id, None, False, "validation_error", "tool_call_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "tool_call_id must be a non-empty string")

    if status is not None and status not in allowed_status:
        _record_request_log(now, workspace_id, None, False, "validation_error", "status must be one of the allowed values")
        return _err("VALIDATION_ERROR", "status must be one of the allowed values")
    if error_code is not None and error_code not in allowed_error_code:
        _record_request_log(now, workspace_id, None, False, "validation_error", "error_code must be one of the allowed values")
        return _err("VALIDATION_ERROR", "error_code must be one of the allowed values")
    if error_message is not None and not isinstance(error_message, str):
        _record_request_log(now, workspace_id, None, False, "validation_error", "error_message must be a string")
        return _err("VALIDATION_ERROR", "error_message must be a string")
    if billed_tokens is not None:
        if not isinstance(billed_tokens, int) or billed_tokens < 0:
            _record_request_log(now, workspace_id, None, False, "validation_error", "billed_tokens must be an integer >= 0")
            return _err("VALIDATION_ERROR", "billed_tokens must be an integer >= 0")

    dt_started = _parse_dt(started_at, "started_at")
    if dt_started in ("TYPE_ERROR", "PARSE_ERROR"):
        _record_request_log(now, workspace_id, None, False, "validation_error", "started_at must be RFC3339 datetime")
        return _err("VALIDATION_ERROR", "started_at must be RFC3339 datetime")
    dt_finished = _parse_dt(finished_at, "finished_at")
    if dt_finished in ("TYPE_ERROR", "PARSE_ERROR"):
        _record_request_log(now, workspace_id, None, False, "validation_error", "finished_at must be RFC3339 datetime")
        return _err("VALIDATION_ERROR", "finished_at must be RFC3339 datetime")
    dt_expires = _parse_dt(expires_at, "expires_at")
    if dt_expires in ("TYPE_ERROR", "PARSE_ERROR"):
        _record_request_log(now, workspace_id, None, False, "validation_error", "expires_at must be RFC3339 datetime")
        return _err("VALIDATION_ERROR", "expires_at must be RFC3339 datetime")

    api_keys = _load("api_keys.json")
    key_row = _find_api_key_row(api_key, api_keys)
    if not key_row or key_row.get("status") != "active":
        _record_request_log(now, workspace_id, None, False, "unauthorized", "Invalid or revoked API key")
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    if key_row.get("workspace_id") != workspace_id:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "unauthorized", "API key does not belong to workspace")
        return _err("UNAUTHORIZED", "API key does not belong to workspace")

    # Update key last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    tool_calls = _load("tool_calls.json")
    tc = None
    for r in tool_calls:
        if isinstance(r, dict) and r.get("id") == tool_call_id:
            tc = r
            break
    if not tc:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "not_found", "Tool call not found")
        return _err("NOT_FOUND", "Tool call not found")

    if tc.get("workspace_id") != workspace_id:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "unauthorized", "Tool call does not belong to workspace")
        return _err("UNAUTHORIZED", "Tool call does not belong to workspace")

    # Must specify at least one field to update
    if status is None and error_code is None and error_message is None and started_at is None and finished_at is None and expires_at is None and billed_tokens is None:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "No updates specified")
        return _err("VALIDATION_ERROR", "No updates specified")

    current_status = tc.get("status")
    if status is not None:
        if current_status not in transitions:
            _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "Tool call has invalid current status")
            return _err("VALIDATION_ERROR", "Tool call has invalid current status")
        if status != current_status and status not in transitions.get(current_status, set()):
            _record_request_log(now, workspace_id, key_row.get("id"), False, "invalid_transition", f"Invalid transition from {current_status} to {status}")
            return _err("INVALID_TRANSITION", f"Invalid transition from {current_status} to {status}")

        # Enforce required timestamps on transition targets
        if status == "running":
            if dt_started is None:
                _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "started_at is required when transitioning to running")
                return _err("VALIDATION_ERROR", "started_at is required when transitioning to running")
        if status in {"succeeded", "failed", "cancelled", "expired"}:
            if dt_finished is None:
                _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "finished_at is required when transitioning to a terminal status")
                return _err("VALIDATION_ERROR", "finished_at is required when transitioning to a terminal status")

    # Validate timestamp ordering (consider existing stored timestamps if not provided)
    existing_started = _parse_dt(tc.get("started_at"), "started_at") if isinstance(tc.get("started_at"), str) else None
    existing_finished = _parse_dt(tc.get("finished_at"), "finished_at") if isinstance(tc.get("finished_at"), str) else None

    eff_started = dt_started if dt_started is not None else existing_started
    eff_finished = dt_finished if dt_finished is not None else existing_finished

    if eff_started and eff_finished and eff_finished < eff_started:
        _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "finished_at must be >= started_at")
        return _err("VALIDATION_ERROR", "finished_at must be >= started_at")

    # If attempting to write results into expired calls, disallow elsewhere; update here is allowed.

    # Apply updates
    if status is not None:
        if status == "running":
            tc["started_at"] = _iso(dt_started)
        if status in {"succeeded", "failed", "cancelled", "expired"}:
            tc["finished_at"] = _iso(dt_finished)
        tc["status"] = status

    # started_at/finished_at/expires_at are only directly set when provided and do not violate ordering
    if status != "running" and dt_started is not None:
        tc["started_at"] = _iso(dt_started)
    if status not in {"succeeded", "failed", "cancelled", "expired"} and dt_finished is not None:
        tc["finished_at"] = _iso(dt_finished)
    if dt_expires is not None:
        tc["expires_at"] = _iso(dt_expires)

    # error_code/message
    if error_code is not None:
        tc["error_code"] = error_code
    if error_message is not None:
        tc["error_message"] = error_message

    # On success completion: apply billed token increments atomically to workspace counters.
    # This endpoint is "primarily used by workers"; we enforce consistency with business rule.
    if status == "succeeded" and billed_tokens is not None:
        if not isinstance(tc.get("started_at"), str):
            _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "started_at must be set before succeeding")
            return _err("VALIDATION_ERROR", "started_at must be set before succeeding")
        if not isinstance(tc.get("finished_at"), str):
            _record_request_log(now, workspace_id, key_row.get("id"), False, "validation_error", "finished_at must be set when succeeding")
            return _err("VALIDATION_ERROR", "finished_at must be set when succeeding")

        workspaces = _load("workspaces.json")
        ws = None
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == workspace_id:
                ws = w
                break
        if not ws:
            _record_request_log(now, workspace_id, key_row.get("id"), False, "not_found", "Workspace not found")
            return _err("NOT_FOUND", "Workspace not found")

        _coerce_current_month(ws, now)

        # Apply increments. (This update tool is called at completion; do not enforce monthly_request_limit here,
        # since it was enforced at acceptance time.)
        ws["requests_used_month"] = int(ws.get("requests_used_month") or 0) + 1
        ws["tokens_used_month"] = int(ws.get("tokens_used_month") or 0) + int(billed_tokens)
        ws["updated_at"] = _iso(now)
        tc["billed_tokens"] = int(billed_tokens)
        tc["updated_at"] = _iso(now)
        _save("workspaces.json", workspaces)
    else:
        if billed_tokens is not None:
            tc["billed_tokens"] = int(billed_tokens)
        tc["updated_at"] = _iso(now)

    _save("tool_calls.json", tool_calls)

    _record_request_log(now, workspace_id, key_row.get("id"), True, normalized_input={"resolved_workspace_id": workspace_id, "tool_call_id": tool_call_id})
    return {"data": tc}

